#include <unity.h>
#include <string.h>
#include "net/ReleaseFormat.h"

void setUp() {}
void tearDown() {}

// Generated by scripts/release.py's signed_message() for the published v1.0.0
// desk image: the firmware must build exactly these bytes to verify it.
static const char* EXPECTED_DESK_V100 =
    "esp32-led-firmware\n"
    "board=esp32_desk_led\n"
    "version=v1.0.0\n"
    "size=951200\n"
    "sha256=5650899ba3877f4430c25ea5fb5b4bf7563352b7ab9fe93379b1128a648e210f\n";

void matchesReleaseScriptOutput() {
    char msg[256];
    int n = formatSignedMessage(msg, sizeof msg, "esp32_desk_led", "v1.0.0", 951200,
                                "5650899ba3877f4430c25ea5fb5b4bf7563352b7ab9fe93379b1128a648e210f");
    TEST_ASSERT_EQUAL_INT((int)strlen(EXPECTED_DESK_V100), n);
    TEST_ASSERT_EQUAL_STRING(EXPECTED_DESK_V100, msg);
}

void reportsTruncation() {
    char msg[16];
    int n = formatSignedMessage(msg, sizeof msg, "esp32_desk_led", "v1.0.0", 951200, "00");
    TEST_ASSERT_TRUE(n >= (int)sizeof msg);   // caller must treat this as failure
}

void hexIsLowercaseLikeHexdigest() {
    const uint8_t bytes[] = {0x00, 0x0f, 0xa5, 0xff};
    char out[9];
    toLowerHex(bytes, sizeof bytes, out);
    TEST_ASSERT_EQUAL_STRING("000fa5ff", out);
}

int main(int, char**) {
    UNITY_BEGIN();
    RUN_TEST(matchesReleaseScriptOutput);
    RUN_TEST(reportsTruncation);
    RUN_TEST(hexIsLowercaseLikeHexdigest);
    return UNITY_END();
}
